/*
 * Responsive variants of the site's images, generated by
 * scripts/optimize-images.py. Each source has AVIF and WebP copies at the
 * widths listed here, named `<name>-<width>.<ext>` beside the original, which
 * stays as the fallback. Keep this list in step with the script.
 */
const projectWidths = [480, 768, 1200, 1600];

const variants = {
  "/assets/about2.png": [360, 560, 840, 1126],
  "/assets/working.jpg": [480, 720, 1080],
  "/projects/fuelup-global.jpg": projectWidths,
  "/projects/viraleety.jpg": projectWidths,
  "/projects/radio-church.jpg": projectWidths,
  "/projects/crudpen.jpg": projectWidths,
  "/projects/grandlife.jpg": projectWidths,
  "/projects/fhapi.jpg": projectWidths,
};

/** `srcset` strings for each modern format, or null for an image without variants. */
export function imageSources(src) {
  const widths = variants[src];
  if (!widths) return null;
  const base = src.replace(/\.[a-z0-9]+$/i, "");
  const set = (ext) => widths.map((width) => `${base}-${width}.${ext} ${width}w`).join(", ");
  return { avif: set("avif"), webp: set("webp") };
}

/** Rendered widths (CSS `sizes`) for the layouts that show images. */
export const imageSizes = {
  // Hero portrait: min(64vw, 270px) on phones, 320px from sm, 420px from lg.
  portrait: "(min-width: 960px) 420px, (min-width: 640px) 320px, min(64vw, 270px)",
  // About: full column on phones, the 5-of-12 column from lg.
  about: "(min-width: 1200px) 520px, (min-width: 960px) 420px, 100vw",
  // Featured rows: 7 of 12 columns from lg, scaled 112% by the parallax wrapper.
  featured: "(min-width: 1200px) 700px, (min-width: 960px) 64vw, 100vw",
  // Catalogue cards: two columns from sm.
  card: "(min-width: 1200px) 540px, (min-width: 640px) 50vw, 100vw",
  cardWide: "(min-width: 1200px) 640px, (min-width: 960px) 58vw, 100vw",
  // Case-study hero: the full container, scaled 110% by the parallax wrapper.
  caseStudy: "(min-width: 1200px) 1232px, 110vw",
};
